{
  "story": "Watch how a recursive function steps down to a base case, then unwinds to solve the full problem.",
  "aha": {
    "stateId": "base",
    "observation": "When the base case is hit, the function stops descending and returns the absolute value 1."
  },
  "layout": {
    "preset": "card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "values": "variant.states.readouts"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "variant.states.why",
        "target": "variant.states.calloutRegion",
        "text": "variant.states.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "variant.states.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Recursion Step",
      "options": ["Start", "Descend 1", "Descend 2", "Base Case", "Unwind 2", "Unwind 1", "Done"]
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Factorial of 3",
        "regions": [
          {
            "id": "stack",
            "label": "Call Stack",
            "kind": "container",
            "values": ["factorial(3)", "factorial(2)", "factorial(1)"]
          },
          {
            "id": "result",
            "label": "Return Value",
            "kind": "value",
            "values": ["?", "?", "1"]
          }
        ],
        "states": [
          {
            "id": "start",
            "label": "Initial Call",
            "short": "f(3)",
            "sentence": "factorial(3) calls factorial(2) multiplying by 3.",
            "why": "Entering the first recursive layer.",
            "active": ["stack"],
            "calloutRegion": "stack",
            "readouts": [
              {
                "id": "depth",
                "label": "Stack Depth",
                "value": "1"
              },
              {
                "id": "val",
                "label": "Current Result",
                "value": "Pending"
              }
            ]
          },
          {
            "id": "desc1",
            "label": "Descend 1",
            "short": "f(2)",
            "sentence": "factorial(2) calls factorial(1) multiplying by 2.",
            "why": "Pushing another frame onto the stack.",
            "active": ["stack"],
            "calloutRegion": "stack",
            "readouts": [
              {
                "id": "depth",
                "label": "Stack Depth",
                "value": "2"
              },
              {
                "id": "val",
                "label": "Current Result",
                "value": "Pending"
              }
            ]
          },
          {
            "id": "base",
            "label": "Base Case",
            "short": "f(1)",
            "sentence": "factorial(1) hits the base case and returns 1 immediately.",
            "why": "Base case reached; stops further recursion.",
            "active": ["result"],
            "calloutRegion": "result",
            "readouts": [
              {
                "id": "depth",
                "label": "Stack Depth",
                "value": "3"
              },
              {
                "id": "val",
                "label": "Current Result",
                "value": "1"
              }
            ]
          },
          {
            "id": "done",
            "label": "Complete",
            "short": "6",
            "sentence": "All frames return, yielding the final product 6.",
            "why": "Unwinding complete.",
            "active": ["result"],
            "calloutRegion": "result",
            "readouts": [
              {
                "id": "depth",
                "label": "Stack Depth",
                "value": "0"
              },
              {
                "id": "val",
                "label": "Current Result",
                "value": "6"
              }
            ]
          }
        ]
      }
    ]
  }
}
